// Adds up the bytes of a buffer.
unsigned sum(const unsigned char *p, unsigned long n) {
    unsigned s = 0;
    while (n--)
        s += *p++;
    return s;
}

// Moves a point by its velocity: loads and stores through one pointer.
struct point {
    long x, y, vx, vy;
};

void move(struct point *p) {
    p->x += p->vx;
    p->y += p->vy;
}

// How many steps the Collatz sequence takes from n down to 1.
unsigned collatz(unsigned long n) {
    unsigned steps = 0;
    while (n != 1) {
        n = n & 1 ? 3 * n + 1 : n >> 1;
        steps++;
    }
    return steps;
}

// Adds up an array of doubles.
double total(const double *v, unsigned long n) {
    double t = 0;
    while (n--)
        t += *v++;
    return t;
}

// Caps the values above a limit and counts them: a loop with a branch inside.
unsigned cap(int *v, unsigned long n, int limit) {
    unsigned capped = 0;
    for (; n--; v++) {
        if (*v > limit) {
            *v = limit;
            capped++;
        }
    }
    return capped;
}
